def is_woodall(n):
    # A Woodall number is of the form n * 2^n - 1 for n >= 1
    if n < 1:
        return False
    # Find k such that k * 2^k - 1 == n
    k = 1
    while True:
        val = k * (2 ** k) - 1
        if val == n:
            return True
        if val > n:
            return False
        k += 1
